function isPalindrome(n) {
  if (n < 0 || (n % 10 === 0 && n !== 0)) return false;
  let reversed = 0, rest = n;
  while (rest > reversed) {
    reversed = reversed * 10 + rest % 10;
    rest = Math.floor(rest / 10);
  }
  return reversed === rest || Math.floor(reversed / 10) === rest;
}
